/* build_pins.h  --  host capture pins consumed by src/handoff_efi.c.
 *
 * In the lab this file was GENERATED from the host's verified boot capture.
 * For publication the host SMBIOS system UUID has been replaced with a zero
 * placeholder; the remaining values (ESP partition device path incl. its GPT
 * partition GUID, the Boot variable sha256, and the chain-loaded loader sha256
 * and byte size) are THIS HOST's real values and must be regenerated for any
 * other host. The writer compares the live SMBIOS UUID and the ESP/loader
 * identity against these pins at run time and refuses on any mismatch by design.
 */
